<template>
  <div class="sec-divider"></div>
  <section id="skills" class="sec" ref="sectionRef">
    <div class="sec-head">
      <span class="sec-tag">{{ t('skills.tag') }}</span>
      <h2 class="sec-title">{{ t('skills.title') }}</h2>
    </div>
    <div class="skill-grid reveal">
      <div class="sg" v-for="group in skillGroups" :key="group.key">
        <div class="sg-title">{{ t(`skills.${group.key}`) }}</div>
        <div class="chips">
          <span class="chip" v-for="chip in group.chips" :key="chip">{{ chip }}</span>
        </div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t } = useI18n()
const skillGroups = [
  { key: 'frontend', chips: ['Vue3', 'TypeScript', 'JavaScript'] },
  { key: 'backend',  chips: ['Spring Boot', 'Redis', 'MySQL', 'Oracle'] },
  { key: 'infra',    chips: ['K8S', 'Docker', 'Git', 'Jenkins'] },
]

const sectionRef = ref(null)
onMounted(() => {
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible')
          observer.unobserve(entry.target)
        }
      })
    },
    { threshold: 0.1 }
  )
  if (sectionRef.value) {
    sectionRef.value.querySelectorAll('.reveal').forEach(el => observer.observe(el))
  }
})
</script>

<style scoped>
.sec {
  position: relative;
  z-index: 2;
  padding: 80px 48px;
  max-width: 1200px;
  margin: 0 auto;
}
.sec-head {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
}
.sec-tag {
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--g);
  background: var(--gb);
  border: 1px solid var(--br2);
  padding: 5px 14px;
  border-radius: 2px;
}
.sec-title {
  font-family: var(--disp);
  font-size: 36px;
  font-weight: 800;
  color: var(--tb);
  letter-spacing: -1.5px;
}
.skill-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.sg {
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 6px;
  padding: 20px 22px;
  transition: border-color 0.2s;
}
.sg:hover { border-color: var(--br2); }
.sg-title {
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--br);
}
.chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  font-size: 12px;
  padding: 4px 10px;
  border: 1px solid var(--br);
  border-radius: 2px;
  color: var(--t);
  background: var(--bg3);
  transition: all 0.15s;
  cursor: default;
}
.chip:hover {
  border-color: var(--g);
  color: var(--g);
  transform: translateY(-2px);
}

@media (max-width: 720px) {
  .sec { padding: 60px 16px; }
  .sec-title { font-size: 24px; }
  .skill-grid { grid-template-columns: 1fr; }
}
</style>
