<template>
  <div class="sec-divider"></div>
  <section id="experience" class="sec">
    <div class="sec-head">
      <span class="sec-tag">{{ t('experience.tag') }}</span>
      <h2 class="sec-title">{{ t('experience.title') }}</h2>
    </div>

    <div
      v-for="(item, i) in items"
      :key="i"
      class="exp-item reveal"
      ref="itemRefs"
    >
      <div class="exp-left">
        <div class="eco">{{ item.company }}</div>
        <div class="eperiod">{{ item.period }}</div>
        <span
          class="ebadge"
          :class="{ amber: item.status === t('experience.contract_end') }"
        >{{ item.status }}</span>
      </div>
      <div class="exp-body">
        <div class="etitle">{{ item.project }}</div>
        <div class="erole">{{ item.role }}</div>
        <ul class="ebullets">
          <li v-for="(bullet, j) in item.bullets" :key="j">{{ bullet }}</li>
        </ul>
        <div v-if="item.tech && item.tech.length" class="etags">
          <span v-for="tag in item.tech" :key="tag" class="etag">{{ tag }}</span>
        </div>
      </div>
    </div>
  </section>
</template>

<script setup>
import { computed, ref, onMounted } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, tm } = useI18n()
const items = computed(() => tm('experience.items'))
const itemRefs = ref([])

onMounted(() => {
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry, i) => {
        if (entry.isIntersecting) {
          setTimeout(() => entry.target.classList.add('visible'), i * 60)
          observer.unobserve(entry.target)
        }
      })
    },
    { threshold: 0.08 }
  )
  itemRefs.value.forEach(el => el && observer.observe(el))
})
</script>

<style scoped>
.sec {
  position: relative;
  z-index: 2;
  padding: 80px 48px;
  max-width: 1200px;
  margin: 0 auto;
}
.sec-head {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 56px;
}
.sec-tag {
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--g);
  background: var(--gb);
  border: 1px solid var(--br2);
  padding: 5px 14px;
  border-radius: 2px;
}
.sec-title {
  font-family: var(--disp);
  font-size: 36px;
  font-weight: 800;
  color: var(--tb);
  letter-spacing: -1.5px;
}

.exp-item {
  display: grid;
  grid-template-columns: 210px 1fr;
  gap: 36px;
  padding: 36px 0;
  border-bottom: 1px solid var(--br);
}
.exp-item:last-child { border-bottom: none; }

.eco {
  font-family: var(--disp);
  font-size: 16px;
  font-weight: 700;
  color: var(--tb);
}
.eperiod {
  font-size: 11px;
  color: var(--tm);
  margin: 4px 0 10px;
  letter-spacing: 0.04em;
}
.ebadge {
  display: inline-block;
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: var(--gb);
  border: 1px solid var(--br2);
  color: var(--g);
  padding: 3px 9px;
  border-radius: 2px;
}
.ebadge.amber {
  background: rgba(255,179,71,0.08);
  border-color: rgba(255,179,71,0.25);
  color: var(--a);
}
.etitle {
  font-family: var(--disp);
  font-size: 21px;
  font-weight: 700;
  color: var(--tb);
  margin-bottom: 6px;
}
.erole {
  font-size: 12px;
  color: var(--a);
  margin-bottom: 16px;
  letter-spacing: 0.05em;
}
.ebullets {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ebullets li {
  font-size: 13px;
  color: var(--t);
  padding-left: 20px;
  position: relative;
  line-height: 1.65;
}
.ebullets li::before {
  content: '▸';
  position: absolute;
  left: 0;
  color: var(--g);
  font-size: 11px;
  top: 2px;
}
.etags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}
.etag {
  font-size: 11px;
  padding: 3px 10px;
  border: 1px solid var(--br);
  border-radius: 2px;
  color: var(--tm);
  transition: all 0.15s;
  cursor: default;
}
.etag:hover { border-color: var(--g); color: var(--g); }

@media (max-width: 720px) {
  .sec { padding: 60px 16px; }
  .sec-title { font-size: 24px; }
  .exp-item { grid-template-columns: 1fr; gap: 12px; }
}
</style>
